def process_upload(filename):
    # Extract and process uploaded file
    ext = filename.rsplit('.', 1)[-1]
    if ext == 'zip':
        os.system(f"unzip -o uploads/{filename} -d extracted/")
    elif ext == 'tar.gz':
        os.system(f"tar -xzf uploads/{filename} -C extracted/")
    elif ext == '7z':
        os.system(f"7z x uploads/{filename} -oextracted/")

    # Convert any images found
    for f in os.listdir('extracted/'):
        subprocess.run(f"convert extracted/{f} output/{f}.png", shell=True)

