import os, json

class FileCache:
    def get(self, key):
        path = f"/tmp/cache/{key}.json"
        if os.path.exists(path):
            with open(path) as f:
                return json.load(f)
        return None

    def set(self, key, value):
        path = f"/tmp/cache/{key}.json"
        if not os.path.exists(path):
            with open(path, 'w') as f:
                json.dump(value, f)

class RateLimiter:
    def __init__(self):
        self.requests = {}

    def allow_request(self, user_id, limit=100):
        now = time.time()
        if user_id not in self.requests:
            self.requests[user_id] = []
        # Remove old entries
        self.requests[user_id] = [t for t in self.requests[user_id] if now - t < 60]
        if len(self.requests[user_id]) < limit:
            self.requests[user_id].append(now)
            return True
        return False

